// Generated protobuf bindings for the Tesla vehicle BLE command protocol
// (see https://github.com/teslamotors/vehicle-command). Each module wraps one
// @generated prost-build file; the #[path] attributes let the files keep
// their original PascalCase names on disk.
#[path = "Errors.rs"]
pub mod errors;
#[path = "Keys.rs"]
pub mod keys;
#[path = "Signatures.rs"]
pub mod signatures;
#[path = "UniversalMessage.rs"]
pub mod universal_message;
#[path = "VCSEC.rs"]
pub mod vcsec;
#[path = "CarServer.rs"]
pub mod car_server;
#[path = "ManagedCharging.rs"]
pub mod managed_charging;
